package io.fireflysoftware.experience.finance.terminal.owner;
import io.fireflysoftware.experience.finance.terminal.owner.impl.*;
import org.fireflyframework.security.api.domain.*;
import org.fireflyframework.security.spi.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import reactor.core.publisher.Mono;
import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;
import org.springframework.web.server.ResponseStatusException;
class StaffBankOwnerReadServiceTest {
 static final Instant NOW=Instant.parse("2026-10-27T12:00:00Z"); final UUID tenant=UUID.randomUUID(),bank=UUID.randomUUID(),enrollment=UUID.randomUUID();
 final StaffBankOwnerQuery query=new StaffBankOwnerQuery(tenant,bank,enrollment,1);
 final String staffActor=UUID.randomUUID().toString();
 SecurityPrincipal actor(){return new SecurityPrincipal("signed-caller","https://issuer.invalid",tenant.toString(),Set.of(),Set.of(),Map.of("exp",NOW.plusSeconds(60)),null,null,Set.of(),Map.of("staffActorId",staffActor));}
 StaffBankOwnerView view(){return new StaffBankOwnerView(tenant,bank,enrollment,1,UUID.randomUUID(),UUID.randomUUID(),Set.of("OPERATIONAL"),1,1,1,1,NOW.plusSeconds(3).toEpochMilli(),NOW.plusSeconds(3).toEpochMilli());}
 StaffBankOwnerReadService service(SecurityContextPort contexts,PolicyDecisionPort policies,OrganizationBankOwnerPort source){return new StaffBankOwnerReadServiceImpl(contexts,policies,source,Clock.fixed(NOW,ZoneOffset.UTC),()->0L);}
 void status(int expected,Runnable call){var e=assertThrows(ResponseStatusException.class,call::run);assertEquals(expected,e.getStatusCode().value());}
 @Test void exactCurrentSummaryRequiresTwoCurrentPolicies(){var count=new AtomicInteger();var expected=view();var s=service(()->Mono.just(actor()),(p,a,r,c)->{assertEquals("terminal.finance.bank-owner.current.read",a);assertEquals(query.resource(),r);count.incrementAndGet();return Mono.just(Decision.permit());},(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(expected,b)));var actual=s.current(query).block();assertEquals(expected.withObservationUntil(actual.observationUntilEpochMillis()),actual);assertTrue(actual.observationUntilEpochMillis()<=expected.observationUntilEpochMillis());assertEquals(2,count.get());}
 @Test void missingCallerDoesNotInvokeCore(){var calls=new AtomicInteger();status(403,()->service(Mono::empty,(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->{calls.incrementAndGet();return Mono.just(new OrganizationBankOwnerPort.Observation(view(),b));}).current(query).block());assertEquals(0,calls.get());}
 @Test void mismatchedTenantDoesNotInvokeCore(){var calls=new AtomicInteger();var a=actor().toBuilder().tenantId(UUID.randomUUID().toString()).build();status(403,()->service(()->Mono.just(a),(p,x,r,c)->Mono.just(Decision.permit()),(q,b,until)->{calls.incrementAndGet();return Mono.just(new OrganizationBankOwnerPort.Observation(view(),b));}).current(query).block());assertEquals(0,calls.get());}
 @Test void initialDenialDoesNotInvokeCore(){var calls=new AtomicInteger();status(403,()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(Decision.deny("ordinary refusal")),(q,b,until)->{calls.incrementAndGet();return Mono.just(new OrganizationBankOwnerPort.Observation(view(),b));}).current(query).block());assertEquals(0,calls.get());}
 @Test void withdrawnFinalPolicyWithholdsSummary(){var calls=new AtomicInteger();status(403,()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(calls.incrementAndGet()==1?Decision.permit():Decision.deny("withdrawn")),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query).block());assertEquals(2,calls.get());}
 @Test void changedPrincipalAtDeliveryRefuses(){var calls=new AtomicInteger();status(403,()->service(()->Mono.just(calls.incrementAndGet()==1?actor():actor().toBuilder().subject("other").build()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query).block());}
 @Test void wrongNativeScopeCannotBeReturned(){status(503,()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(new StaffBankOwnerView(tenant,bank,UUID.randomUUID(),1,UUID.randomUUID(),UUID.randomUUID(),Set.of("OPERATIONAL"),1,1,1,1,NOW.plusSeconds(3).toEpochMilli(),NOW.plusSeconds(3).toEpochMilli()),b))).current(query).block());}
 @Test void expiredNativeWindowCannotBeReturned(){status(503,()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(new StaffBankOwnerView(tenant,bank,enrollment,1,UUID.randomUUID(),UUID.randomUUID(),Set.of("OPERATIONAL"),1,1,1,1,NOW.toEpochMilli(),NOW.toEpochMilli()),b))).current(query).block());}
 @Test void coreSuspensionRemainsConflict(){status(409,()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.error(new ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT))).current(query).block());}
 @Test void callerWithoutValidatedExpiryCannotBePromoted(){status(403,()->service(()->Mono.just(actor().toBuilder().claims(Map.of()).build()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query).block());}
 @Test void scopeRequiresPositiveExactRevision(){assertThrows(IllegalArgumentException.class,()->new StaffBankOwnerQuery(tenant,bank,enrollment,0));}

 void bounded(java.util.function.Supplier<Mono<StaffBankOwnerView>> operation){reactor.test.StepVerifier.withVirtualTime(operation).thenAwait(Duration.ofSeconds(11)).expectErrorMatches(e->e instanceof ResponseStatusException r&&r.getStatusCode().value()==503).verify(Duration.ofSeconds(2));}
 @Test void stalledInitialPrincipalCannotOutliveOriginalBudget(){bounded(()->service(Mono::never,(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query));}
 @Test void stalledInitialPolicyCannotOutliveOriginalBudget(){bounded(()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.never(),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query));}
 @Test void stalledCoreCannotOutliveOriginalBudget(){bounded(()->service(()->Mono.just(actor()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->Mono.never()).current(query));}
 @Test void stalledFinalPolicyCannotOutliveNativeWindow(){var count=new AtomicInteger();bounded(()->service(()->Mono.just(actor()),(p,a,r,c)->count.incrementAndGet()==1?Mono.just(Decision.permit()):Mono.never(),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view(),b))).current(query));assertEquals(2,count.get());}
 @Test void missingTrustedStaffProjectionCannotInvokeDomain(){var count=new AtomicInteger();status(403,()->service(()->Mono.just(actor().toBuilder().attributes(Map.of()).build()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->{count.incrementAndGet();return Mono.just(new OrganizationBankOwnerPort.Observation(view(),b));}).current(query).block());assertEquals(0,count.get());}
 @Test void exactOriginalStaffExpiryIsForwardedWithoutRenewal(){var expiry=NOW.plusSeconds(1);var seen=new AtomicReference<Instant>();var actual=service(()->Mono.just(actor().toBuilder().claims(Map.of("exp",expiry)).build()),(p,a,r,c)->Mono.just(Decision.permit()),(q,b,until)->{seen.set(until);return Mono.just(new OrganizationBankOwnerPort.Observation(view(),b));}).current(query).block();assertEquals(expiry,seen.get());assertTrue(actual.observationUntilEpochMillis()<=expiry.toEpochMilli());}
 @Test void earlierDomainHandoffWindowBoundsFinalStaffPolicy(){var count=new AtomicInteger();reactor.test.StepVerifier.withVirtualTime(()->service(()->Mono.just(actor()),(p,a,r,c)->count.incrementAndGet()==1?Mono.just(Decision.permit()):Mono.never(),(q,b,until)->Mono.just(new OrganizationBankOwnerPort.Observation(view().withObservationUntil(NOW.plusSeconds(1).toEpochMilli()),b))).current(query)).thenAwait(Duration.ofSeconds(2)).expectErrorMatches(e->e instanceof ResponseStatusException r&&r.getStatusCode().value()==503).verify(Duration.ofMillis(300));}
}
